import{_ as e,o,c as s,a2 as t}from"./chunks/framework.CiKk3sJz.js";const u=JSON.parse('{"title":"漫画 · 第 26 话 :has() 选择器：CSS 的「父选择器」","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.26-has-selector.md","filePath":"comics/css/EP.26-has-selector.md","lastUpdated":1792579602000}'),c={name:"comics/css/EP.26-has-selector.md"};function r(i,a,d,h,l,n){return o(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="漫画-·-第-26-话-has-选择器-css-的「父选择器」" tabindex="-1">漫画 · 第 26 话 :has() 选择器：CSS 的「父选择器」 <a class="header-anchor" href="#漫画-·-第-26-话-has-选择器-css-的「父选择器」" aria-label="Permalink to &quot;漫画 · 第 26 话 :has() 选择器：CSS 的「父选择器」&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/16-has-selector">docs/css/16-has-selector.md</a> ｜ 原画：<a href="./EP.26-has-selector.svg">EP.26-has-selector.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。每次遇到「卡片有图/无图」「表单是否有效」「导航有没有子菜单」都要写 JS 检测子元素再切换类名，样式逻辑分散在 JS 和 CSS 两处。</li><li><strong>标签君</strong>：HTML5 结构师，搬出 <code>:has()</code> 选择器，让 CSS 从「只能向下选」进化为「可以向上选」，DOM 反向匹配零 JS。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>选择器章（EP.01）讲了后代、子代、兄弟选择器，但都是单向的——只能从父到子、从前到后。像素酱被「选中包含图片的卡片」折磨：JS 检测、类名切换、SSR 样式闪烁。标签君引入 <code>:has()</code>，相对选择器作为参数，实现父选择器、兄弟前置选择器、数量感知布局。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>CSS 单向选择限制：<code>.parent .child</code> 只能向下，<code>prev + next</code> 只能向后。「如何选中包含 .child 的父元素？」传统方案是 JS 检测 + 类名切换，导致 JS 与 CSS 耦合、SSR 时样式闪烁、新增状态需改两处。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>:has()</code> 接受相对选择器参数：<code>.card:has(img)</code> 匹配包含图片的卡片，<code>img:has(+ figcaption)</code> 匹配后面跟着标题的图片，<code>form:has(input:invalid)</code> 匹配有无效字段的表单。DOM 变化时自动重新匹配，无需 JS 监听。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大实战场景：表单验证（<code>form:has(input:invalid)</code> 禁用提交按钮）、卡片有图变布局（<code>.card:has(img)</code> 切换 flex 方向）、导航子菜单标记（<code>li:has(&gt; ul)</code> 添加箭头）、数量感知布局（<code>:has(&gt; :nth-child(5))</code> 检测子元素数量）。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>:has() 接受相对选择器，实现「父选择器」和「兄弟前置选择器」。</li><li>表单验证、卡片布局、导航标记、数量感知——四大场景零 JS。</li><li>性能注意：避免 :has(*)，尽量用子选择器（＞）缩小匹配范围。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：<code>:not(:has(img))</code> 和 <code>:has(:not(img))</code> 语义相同吗？为什么？</p><p><strong>答</strong>：不同。<code>:not(:has(img))</code> 表示「不包含 img 的元素」——对元素的否定。<code>:has(:not(img))</code> 表示「包含至少一个非 img 子元素的元素」——对子元素的否定。前者是「没有图片」，后者是「有非图片内容」。一个包含图片和文字的 div 会匹配 <code>:has(:not(img))</code> 但不匹配 <code>:not(:has(img))</code>。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>父选择器基础 + 表单验证状态 + 数量感知布局 + 兄弟前置选择 + 导航子菜单标记：<a href="./../../examples/css/16-has-selector/index-01-has-selector.html">examples/css/16-has-selector/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 27 话《View Transitions》——<code>document.startViewTransition()</code> 与 <code>view-transition-name</code>，页面/元素过渡动画，单页应用体验升级的关键 API。</p>',22)])])}const p=e(c,[["render",r]]);export{u as __pageData,p as default};
